package rw.schoolpass.web;
import jakarta.validation.constraints.*;
public class StudentForm { @NotBlank private String studentCode; @NotBlank private String firstName; @NotBlank private String lastName; @NotBlank private String className; private String section=""; @NotBlank private String schoolName; @NotBlank private String principalName; @NotBlank private String academicYear; @Min(0) private long feeRequired; @Min(0) private long feePaid; private String uniformStatus="UNPAID";
 public String getStudentCode(){return studentCode;} public void setStudentCode(String v){studentCode=v;} public String getFirstName(){return firstName;} public void setFirstName(String v){firstName=v;} public String getLastName(){return lastName;} public void setLastName(String v){lastName=v;} public String getClassName(){return className;} public void setClassName(String v){className=v;} public String getSection(){return section;} public void setSection(String v){section=v;} public String getSchoolName(){return schoolName;} public void setSchoolName(String v){schoolName=v;} public String getPrincipalName(){return principalName;} public void setPrincipalName(String v){principalName=v;} public String getAcademicYear(){return academicYear;} public void setAcademicYear(String v){academicYear=v;} public long getFeeRequired(){return feeRequired;} public void setFeeRequired(long v){feeRequired=v;} public long getFeePaid(){return feePaid;} public void setFeePaid(long v){feePaid=v;} public String getUniformStatus(){return uniformStatus;} public void setUniformStatus(String v){uniformStatus=v;} }
